const shop = 'vdzvc0-nd';

// Zeitfenster: 17.02.2026 00:00 bis 17.07.2026 14:00 (MESZ)
const since = '2026-06-16T23:00:00Z'; // 17.02.2026 00:00 MESZ
const until = '2026-07-17T12:00:00Z'; // 17.07.2026 14:00 MESZ

const initUrl = `https://${shop}.myshopify.com/admin/api/2024-10/orders.json`
  + `?limit=250`
  + `&status=any`
  + `&created_at_min=${encodeURIComponent(since)}`
  + `&created_at_max=${encodeURIComponent(until)}`
  + `&since_id=0`
  + `&fields=id,name,created_at,tags,line_items`;

const staticData = $getWorkflowStaticData('global');
staticData.toFix = [];

return [{
  json: {
    nextUrl: initUrl,
    hasNext: true,
    accessToken: $('Token holen ').item.json.access_token
  }
}];

const response = $input.first().json;
const orders = response.body?.orders || response.orders || [];

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.toFix)) {
  staticData.toFix = [];
}

// Teilpositionen der Liebesbüchse Adventsbox
const SKU_BUECHER = 'LB-A-2026-01';
const SKU_GOODIES = 'LB-A-2026-02';
const VARIANT_BUECHER = '8298440523891'; // Ziel-Variante 42,00 EUR
const VARIANT_GOODIES = '8298440589427'; // Ziel-Variante 26,99 EUR

let maxId = 0;

for (const order of orders) {
  if (order.id > maxId) maxId = order.id;

  const lineItems = order.line_items || [];
  const positionen = [];

  for (const li of lineItems) {
    const sku = String(li.sku || '').trim();
    if (sku === SKU_BUECHER) {
      positionen.push({
        typ: 'buecher',
        lineItemId: li.id,
        title: li.title,
        sku: sku,
        newVariantId: VARIANT_BUECHER,
        aktuellerPreis: li.price,
        quantity: li.quantity
      });
    } else if (sku === SKU_GOODIES) {
      positionen.push({
        typ: 'goodies',
        lineItemId: li.id,
        title: li.title,
        sku: sku,
        newVariantId: VARIANT_GOODIES,
        aktuellerPreis: li.price,
        quantity: li.quantity
      });
    }
  }

  if (positionen.length > 0) {
    staticData.toFix.push({
      orderId: order.id,
      orderName: order.name,
      createdAt: order.created_at,
      positionen: positionen
    });
  }
}

// Nächste Seite über since_id = höchste gesehene ID
const shop = 'vdzvc0-nd';
const since = '2026-02-16T23:00:00Z';
const until = '2026-07-17T12:00:00Z';

let nextUrl = null;
if (orders.length === 250) {
  nextUrl = `https://${shop}.myshopify.com/admin/api/2024-10/orders.json`
    + `?limit=250`
    + `&status=any`
    + `&created_at_min=${encodeURIComponent(since)}`
    + `&created_at_max=${encodeURIComponent(until)}`
    + `&since_id=${maxId}`
    + `&fields=id,name,created_at,tags,line_items`;
}

return [{
  json: {
    nextUrl: nextUrl,
    hasNext: !!nextUrl,
    collectedCount: staticData.toFix.length
  }
}];

const tokenItem = $input.first().json;
const urlItem = $input.last().json;

return [{
  json: {
    accessToken: tokenItem.access_token,
    nextUrl: urlItem.nextUrl,
    hasNext: urlItem.hasNext
  }
}];

const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];

return collected.map(row => ({ json: row }));

// Bereitet je gefundene Bestellung EIN Item vor (mit allen Teilpositionen)
const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];

const out = [];
for (const order of collected) {
  out.push({
    json: {
      orderId: order.orderId,
      orderName: order.orderName,
      orderGid: `gid://shopify/Order/${order.orderId}`,
      // Positionen mit GIDs für Add (Variante) und Remove (altes LineItem)
      positionen: order.positionen.map(pos => ({
        typ: pos.typ,
        oldLineItemGid: `gid://shopify/CalculatedLineItem/${pos.lineItemId}`,
        newVariantGid: `gid://shopify/ProductVariant/${pos.newVariantId}`,
        quantity: pos.quantity
      }))
    }
  });
}

return out;

const resp = $input.first().json;
const begin = resp?.data?.orderEditBegin;
const errs = begin?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditBegin userErrors: ' + JSON.stringify(errs));
}
const calcOrderId = begin?.calculatedOrder?.id;
if (!calcOrderId) {
  throw new Error('Keine calculatedOrder.id erhalten: ' + JSON.stringify(resp));
}

return [{
  json: {
    calcOrderId,
    orderName: $('Loop Over Items').item.json.orderName,
    orderGid: $('Loop Over Items').item.json.orderGid,
    positionen: $('Loop Over Items').item.json.positionen
  }
}];

const resp = $input.first().json;
const data = resp?.data || {};

// Alle aliasierten orderEditAddVariant-Ergebnisse prüfen (a0, a1, ...)
for (const key of Object.keys(data)) {
  const errs = data[key]?.userErrors || [];
  if (errs.length) {
    throw new Error(`orderEditAddVariant (${key}) userErrors: ` + JSON.stringify(errs));
  }
}

return [{
  json: {
    calcOrderId: $('CalcOrder auslesen').item.json.calcOrderId,
    orderName: $('CalcOrder auslesen').item.json.orderName,
    orderGid: $('CalcOrder auslesen').item.json.orderGid,
    positionen: $('CalcOrder auslesen').item.json.positionen,
    addResult: data
  }
}];

const resp = $input.first().json;
const commit = resp?.data?.orderEditCommit;
const errs = commit?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditCommit userErrors: ' + JSON.stringify(errs));
}

return [{
  json: {
    status: 'OK',
    orderName: $('Add-Ergebnis prüfen').item.json.orderName,
    committedOrder: commit?.order || null
  }
}];

const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];

// Beim Testlauf wurde nur die erste Bestellung verarbeitet
const getestet = collected.length ? collected[0] : null;

return [{
  json: {
    hinweis: 'Diese Bestellung wurde im Testlauf korrigiert – in Shopify kontrollieren:',
    orderName: getestet ? getestet.orderName : 'keine Bestellung gefunden',
    orderId: getestet ? getestet.orderId : null
  }
}];

const orderGid = $('Loop Over Items').item.json.orderGid;

const body = {
  query: `mutation orderEditBegin($id: ID!) { orderEditBegin(id: $id) { calculatedOrder { id } userErrors { field message } } }`,
  variables: { id: orderGid }
};

return [{
  json: {
    accessToken: $('Token holen 2').item.json.access_token,
    gqlBody: JSON.stringify(body)
  }
}];

const item = $input.item.json;
const positionen = item.positionen || [];

// Eine Mutation mit einem aliasierten orderEditAddVariant je Position
const parts = positionen.map((pos, i) => {
  return `a${i}: orderEditAddVariant(id: $id, variantId: $variantId${i}, quantity: $quantity${i}, allowDuplicates: true) {
    calculatedLineItem { id title sku variantTitle discountedUnitPriceSet { shopMoney { amount currencyCode } } }
    userErrors { field message }
  }`;
});

const varDefs = ['$id: ID!'];
const variables = { id: item.calcOrderId };
positionen.forEach((pos, i) => {
  varDefs.push(`$variantId${i}: ID!`);
  varDefs.push(`$quantity${i}: Int!`);
  variables[`variantId${i}`] = pos.newVariantGid;
  variables[`quantity${i}`] = pos.quantity;
});

const body = {
  query: `mutation orderEditAddVariants(${varDefs.join(', ')}) {
    ${parts.join('\n')}
  }`,
  variables
};

return {
  json: {
    ...item,
    accessToken: $('Token holen 2').item.json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const item = $input.item.json;
const positionen = item.positionen || [];

// Eine Mutation mit einem aliasierten orderEditSetQuantity je alter Position
const parts = positionen.map((pos, i) => {
  return `s${i}: orderEditSetQuantity(id: $id, lineItemId: $lineItemId${i}, quantity: 0, restock: false) {
    calculatedLineItem { id quantity }
    userErrors { field message }
  }`;
});

const varDefs = ['$id: ID!'];
const variables = { id: item.calcOrderId };
positionen.forEach((pos, i) => {
  varDefs.push(`$lineItemId${i}: ID!`);
  variables[`lineItemId${i}`] = pos.oldLineItemGid;
});

const body = {
  query: `mutation orderEditSetQuantities(${varDefs.join(', ')}) {
    ${parts.join('\n')}
  }`,
  variables
};

return {
  json: {
    ...item,
    accessToken: $('Token holen 2').item.json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.item.json;
const data = resp?.data || {};

// Alle aliasierten orderEditSetQuantity-Ergebnisse prüfen (s0, s1, ...)
for (const key of Object.keys(data)) {
  const errs = data[key]?.userErrors || [];
  if (errs.length) {
    throw new Error(`orderEditSetQuantity (${key}) userErrors: ` + JSON.stringify(errs));
  }
}

return {
  json: {
    ...$('Add-Ergebnis prüfen').item.json,
    oldPositionsRemoved: true,
    removeResult: data
  }
};

// CSV-Vorbereitung: eine Zeile pro Teilposition
const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];

const zielPreise = {
  buecher: '42.00',
  goodies: '26.99'
};

const rows = [];
for (const order of collected) {
  for (const pos of order.positionen) {
    rows.push({
      orderId: order.orderId,
      orderName: order.orderName,
      createdAt: order.createdAt,
      typ: pos.typ,
      sku: pos.sku,
      title: pos.title,
      lineItemId: pos.lineItemId,
      quantity: pos.quantity,
      aktuellerPreis: pos.aktuellerPreis,
      zielPreis: zielPreise[pos.typ] || '',
      newVariantId: pos.newVariantId
    });
  }
}

return rows.map(r => ({ json: r }));
